/* Quiet application chrome. Queues and conflict actions remain available on demand. */
(()=>{'use strict';const S=window.AtelierStudio,V=window.StudioVault,previous=render;let wasSettings=false,openGroups=new Set();
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e},btn=(text,fn,cls='')=>{const e=node('button',text,cls);e.type='button';e.onclick=fn;return e};
function snapshot(){const legacy=(window.atelierOffline?.pending||[]).filter(j=>j.base===pcUrl),studio=(V?.pending()||[]).filter(j=>j.base===pcUrl);let groceries=[];try{groceries=JSON.parse(localStorage.getItem('goblin-groceries-v1:'+pcUrl)||'{}').jobs||[]}catch{}const all=[...legacy,...studio,...groceries];return {legacy,studio,groceries,count:all.length,conflict:all.some(j=>!!j.conflict),connected:!!pcUrl&&online,error:V?.status().error||error||window.atelierGroceries?.error||''}}
function paint(){const gear=document.getElementById('quickSettings');if(!gear)return;const s=snapshot();let badge=document.getElementById('mobileConnectionBadge');if(!badge){badge=node('span');badge.id='mobileConnectionBadge';badge.setAttribute('aria-hidden','true');gear.append(badge)}badge.hidden=(!pcUrl&&!s.count)||(s.connected&&!s.count&&!s.conflict);badge.classList.toggle('has-count',s.count>0);badge.classList.toggle('conflict',s.conflict);badge.textContent=s.count?String(Math.min(s.count,9))+(s.count>9?'+':''):'';gear.setAttribute('aria-description',s.count?s.count+' modification(s) conservée(s) sur ce téléphone'+(s.conflict?' · conflit à examiner':''):s.connected?'PC connecté':'PC indisponible');gear.dataset.connection=s.conflict?'conflict':s.count?'pending':s.connected?'connected':'offline'}
function settingsGroup(name){return [...document.querySelectorAll('#content .settings-group')].find(g=>g.querySelector(':scope > summary')?.textContent===name)}
function details(){window.openModal('<div id="mobileSyncDetails"></div>');drawDetails()}
function drawDetails(){const host=document.getElementById('mobileSyncDetails');if(!host)return;host.replaceChildren();const s=snapshot();host.append(node('h2','Connexion au PC'),node('p',s.conflict?'Une modification demande ton choix.':s.connected?'PC connecté':pcUrl?'PC indisponible':'PC non relié'));
 if(s.count)host.append(node('p',s.count+' modification(s) conservée(s) sur ce téléphone.'));
 const retry=btn('Réessayer',async()=>{retry.disabled=true;try{await Promise.allSettled([window.atelierOffline?.drain(),V?.drain(),window.atelierGroceries?.drain(),syncPull({quiet:true})]);await S.refresh()}finally{paint();drawDetails()}},'action sync-primary');if(pcUrl)host.append(retry);
 if(s.legacy.length){window.atelierOffline.renderOutbox(host);const box=host.querySelector('#syncOutboxPanel');box?.querySelector('h2')?.remove();for(const b of box?.querySelectorAll('button')||[])if(b.textContent==='Réessayer la synchronisation')b.remove()}
 for(const job of s.studio){const row=node('section',undefined,'panel');row.append(node('strong',job.payload?.title||job.payload?.name||'Modification locale'));if(job.conflict){row.append(node('p',job.conflict),btn('Garder la version du PC',async()=>{await V.discard(job);await S.refresh();drawDetails()}))}host.append(row)}
 if(s.groceries.length)host.append(node('p',s.groceries.length+' modification(s) des courses en attente.'));if(window.atelierGroceries?.error?.startsWith('Conflit'))host.append(btn('Ouvrir mes courses',()=>{window.closeModal();state.page='connected';tab='shopping';render()}));
 const technical=node('details',undefined,'mobile-technical');technical.append(node('summary','Détails de connexion'));if(s.error)technical.append(node('p',s.error));technical.append(node('p',pcUrl||'Aucune adresse enregistrée.'));if(!s.connected&&pcUrl)technical.append(node('p','Vérifie que Tailscale est actif sur les deux appareils et que L’Atelier est ouvert sur le PC.'));host.append(technical,btn('Réglages du PC',()=>{window.closeModal();state.page='settings';render();const group=settingsGroup('Connexion au PC');if(group){group.open=true;group.scrollIntoView({block:'start'})}}));
}
function simplifySettings(){
 const extra=settingsGroup('Albums, trackers et widget'),navigation=settingsGroup('Accueil et navigation');if(extra&&navigation){const widget=node('details',undefined,'mobile-technical');widget.append(node('summary','Widget d’accueil'));for(const p of extra.querySelectorAll('p'))if(p.textContent.startsWith('Le widget'))widget.append(p);navigation.querySelector('.panel')?.append(widget);extra.remove()}
 const connection=settingsGroup('Connexion au PC');if(connection&&!connection.querySelector('[data-connection-details]')){const button=btn('Connexion et modifications',details,'action');button.dataset.connectionDetails='1';connection.querySelector('.panel')?.prepend(button)}
 for(const group of document.querySelectorAll('#content .settings-group')){const name=group.querySelector(':scope > summary')?.textContent;group.open=openGroups.has(name);group.addEventListener('toggle',()=>{if(group.open)openGroups.add(name);else openGroups.delete(name)})}
 const update=settingsGroup('Mises à jour')?.querySelector('.panel');if(update){const advanced=node('details',undefined,'mobile-technical');advanced.append(node('summary','Options et informations'));for(const child of [...update.children]){if(child.tagName==='H2')continue;const text=child.textContent||'',id=child.id;const primary=id==='goblinInstalledVersion'||id==='goblinUpdateStatus'||id==='goblinInstallUpdate'||child.tagName==='BUTTON'&&text.includes('Vérifier les mises à jour');if(!primary){if(child.tagName==='BUTTON'&&text.includes('Chercher une nouvelle version TEST en 1 clic'))child.remove();else advanced.append(child)}}update.append(advanced)}
}
function tidy(){const host=document.getElementById('content');for(const el of host.querySelectorAll('#syncOutboxPanel,.studio-mobile-status'))el.remove();
 const drafts=[...host.querySelectorAll(':scope > .panel')].filter(p=>[...p.querySelectorAll('button')].some(b=>b.textContent.startsWith('Reprendre un brouillon')));for(const box of drafts){if(state.page==='settings'){const target=settingsGroup('Sauvegardes et données');if(target){const d=node('details',undefined,'mobile-technical mobile-drafts');d.append(node('summary','Brouillons conservés'));for(const p of box.querySelectorAll(':scope > p'))p.remove();d.append(box);target.querySelector('.panel')?.append(d)}}else box.remove()}
 if(state.page==='settings')simplifySettings();paint()
}
render=function(){if(state.page==='settings'&&wasSettings){openGroups=new Set([...document.querySelectorAll('#content .settings-group[open]')].map(g=>g.querySelector(':scope > summary')?.textContent))}else if(state.page==='settings')openGroups.clear();wasSettings=state.page==='settings';const result=previous();tidy();return result};
const appbar=document.querySelector('body>header');new ResizeObserver(()=>document.documentElement.style.setProperty('--mobile-header-height',appbar.getBoundingClientRect().height+'px')).observe(appbar);
window.MobileChrome={paint,details,snapshot};window.addEventListener('studio-queue-updated',paint);window.addEventListener('online',paint);window.addEventListener('offline',paint);setInterval(paint,2000);render();
})();
